using System;
using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

public class PoolHandler : ReferenceSingleton<PoolHandler>
{
	[Serializable]
	public struct PoolData
	{
		public string key;

		public Transform bank;

		public Transform actionParent;

		public GameObject prefab;

		public PoolData(GameObject prefab, Transform poolParent, Transform objParent)
		{
			this.prefab = prefab;
			key = prefab.name;
			actionParent = objParent;
			bank = new GameObject(key + "Pool").transform;
			bank.SetParent(poolParent);
			bank.transform.position = Vector3.zero;
			bank.gameObject.SetActive(value: false);
		}

		public GameObject GetObject()
		{
			return ObjSetup();
		}

		public GameObject GetObject(Vector3 spawnLocalPos)
		{
			GameObject gameObject = ObjSetup();
			gameObject.transform.localPosition = spawnLocalPos;
			return gameObject;
		}

		private GameObject ObjSetup()
		{
			GameObject gameObject = null;
			gameObject = ((bank.childCount <= 0) ? UnityEngine.Object.Instantiate(prefab) : bank.GetChild(0).gameObject);
			gameObject.name = key;
			gameObject.transform.SetParent(actionParent);
			gameObject.transform.localScale = prefab.transform.localScale;
			return gameObject;
		}

		public void StoreObject(GameObject obj)
		{
			obj.transform.SetParent(bank);
		}
	}

	public Transform poolHost;

	public Transform objHost;

	[SerializeField]
	private GameObject[] preAddPools;

	public List<PoolData> pools = new List<PoolData>();

	protected override void Awake()
	{
		base.Awake();
		InitializePreAddPools();
	}

	[Button(null)]
	public void InitializePreAddPools()
	{
		ClearAllPools();
		for (int i = 0; i < preAddPools.Length; i++)
		{
			AddPool(preAddPools[i]);
		}
	}

	[Button(null)]
	public void ClearAllPools()
	{
		pools.InteractThroughItems(delegate(PoolData pool)
		{
			UnityEngine.Object.DestroyImmediate(pool.bank.gameObject);
		});
		pools.Clear();
	}

	public void SetHost(Transform host)
	{
		objHost = host;
	}

	public void AddPool(GameObject prefab, Transform objParent)
	{
		PoolData item = new PoolData(prefab, poolHost, objParent);
		for (int i = 0; i < pools.Count; i++)
		{
			if (pools[i].prefab == prefab)
			{
				Debug.Log("Object pool already exists: " + prefab.name);
				return;
			}
		}
		pools.Add(item);
	}

	public void AddPool(GameObject prefab)
	{
		AddPool(prefab, null);
	}

	public void AddPool(GameObject[] prefabs)
	{
		AddPool(prefabs, null);
	}

	public void AddPool(GameObject[] prefabs, Transform parent)
	{
		for (int i = 0; i < prefabs.Length; i++)
		{
			AddPool(prefabs[i], parent);
		}
	}

	public GameObject GetObject(string key)
	{
		GameObject result = null;
		for (int i = 0; i < pools.Count; i++)
		{
			if (pools[i].key == key)
			{
				return pools[i].GetObject();
			}
		}
		return result;
	}

	public GameObject GetObject(string key, Vector3 position)
	{
		GameObject result = null;
		for (int i = 0; i < pools.Count; i++)
		{
			if (pools[i].key == key)
			{
				result = pools[i].GetObject();
				if (result != null)
				{
					result.transform.localPosition = position;
				}
				return result;
			}
		}
		return result;
	}

	public GameObject GetObject(string key, float returnTime)
	{
		GameObject @object = GetObject(key);
		if (@object != null)
		{
			StoreObject(@object, returnTime);
		}
		return @object;
	}

	public GameObject GetObject(string key, Vector3 position, float returnTime)
	{
		GameObject @object = GetObject(key, position);
		if (@object != null)
		{
			StoreObject(@object, returnTime);
		}
		return @object;
	}

	public GameObject GetObject(string key, Vector3 localPosition, Transform parent, float returnTime)
	{
		GameObject @object = GetObject(key);
		if (@object != null)
		{
			Vector3 localScale = @object.transform.localScale;
			@object.transform.SetParent(parent);
			@object.transform.localPosition = localPosition;
			@object.transform.localScale = localScale;
			StoreObject(@object, returnTime);
		}
		return @object;
	}

	public GameObject GetObject(string key, Vector3 localPosition, Transform parent)
	{
		GameObject @object = GetObject(key);
		if (@object != null)
		{
			Vector3 localScale = @object.transform.localScale;
			@object.transform.SetParent(parent);
			@object.transform.localPosition = localPosition;
			@object.transform.localScale = localScale;
		}
		return @object;
	}

	public GameObject GetObject(string key, Transform parent, float returnTime)
	{
		return GetObject(key, Vector3.zero, parent, returnTime);
	}

	public GameObject GetObject(string key, Transform parent)
	{
		return GetObject(key, Vector3.zero, parent);
	}

	public void StoreObject(GameObject input)
	{
		int num = -1;
		string text = "";
		if (input == null)
		{
			Debug.Log(input.name);
			return;
		}
		for (int i = 0; i < pools.Count; i++)
		{
			if (input.name.Contains(pools[i].key) && pools[i].key.Length > text.Length)
			{
				num = i;
				text = pools[i].key;
			}
		}
		if (num >= 0)
		{
			pools[num].StoreObject(input);
		}
	}

	public void StoreObject(GameObject input, float delay)
	{
		InvokeAlternatives.Invoke(this, delay, delegate
		{
			StoreObject(input);
		});
	}
}
